export const s12AccountancyHi: Record<string, { stem: string; options: string[]; explanation: string }> = {
  "s12acc-b-001": { stem: "एक व्यापारी की प्रारंभिक पूँजी ₹3,50,000 थी। वर्ष के अंत में उसकी परिसंपत्तियाँ ₹6,20,000 और बाह्य देयताएँ ₹1,70,000 थीं। वर्ष के दौरान उसने ₹40,000 अतिरिक्त पूँजी लगाई और ₹25,000 का आहरण किया। वर्ष का लाभ है:", options: ["₹85,000","₹1,00,000","₹1,15,000","₹70,000"], explanation: "अंतिम पूँजी = 6,20,000 − 1,70,000 = ₹4,50,000। लाभ = अंतिम पूँजी − प्रारंभिक पूँजी − अतिरिक्त पूँजी + आहरण = 4,50,000 − 3,50,000 − 40,000 + 25,000 = ₹85,000।" },
  "s12acc-b-002": { stem: "स्थायी परिसंपत्तियाँ तुलन पत्र में लागत में से मूल्यह्रास घटाकर दिखाई जाती हैं, न कि उनके वर्तमान वसूली योग्य मूल्य पर। यह व्यवहार मुख्यतः किस अवधारणा पर आधारित है?", options: ["मुद्रा मापन की अवधारणा","निरंतरता (चालू व्यवसाय) की अवधारणा","लेखांकन अवधि की अवधारणा","द्विपक्षीय अवधारणा"], explanation: "व्यवसाय को निकट भविष्य तक चलते रहने वाला माना जाता है, अतः स्थायी परिसंपत्तियाँ उपयोग के लिए रखी जाती हैं, बिक्री के लिए नहीं, इसलिए उनका वसूली मूल्य प्रासंगिक नहीं है।" },
  "s12acc-b-003": { stem: "अंतिम स्टॉक का मूल्यांकन लागत या शुद्ध वसूली योग्य मूल्य, जो भी कम हो, पर करना किसका प्रयोग है?", options: ["एकरूपता","सारता","रूढ़िवादिता (विवेकशीलता)","पूर्ण प्रकटीकरण"], explanation: "रूढ़िवादिता के अनुसार संभावित हानियों का प्रावधान किया जाता है, परंतु संभावित लाभों को मान्यता नहीं दी जाती; लागत या शुद्ध वसूली मूल्य में से कम वाला नियम यही करता है।" },
  "s12acc-b-004": { stem: "मार्च 2025 का वेतन अप्रैल 2025 में चुकाया जाता है, परंतु इसे 31 मार्च 2025 को समाप्त वर्ष के लाभ-हानि खाते में चार्ज किया जाता है। यह किसका पालन है?", options: ["मुद्रा मापन की अवधारणा","व्यावसायिक इकाई की अवधारणा","ऐतिहासिक लागत की अवधारणा","मिलान की अवधारणा"], explanation: "मिलान की अवधारणा के अनुसार किसी अवधि के आगम अर्जित करने में हुए व्यय उसी अवधि में चार्ज किए जाते हैं, चाहे उनका भुगतान हुआ हो या नहीं।" },
  "s12acc-b-005": { stem: "स्वामी ₹5,000 लागत का माल व्यवसाय से निजी उपयोग के लिए ले जाता है। रोज़नामचा प्रविष्टि है:", options: ["आहरण खाता नाम, क्रय खाते से ₹5,000","आहरण खाता नाम, विक्रय खाते से ₹5,000","क्रय खाता नाम, आहरण खाते से ₹5,000","पूँजी खाता नाम, रोकड़ खाते से ₹5,000"], explanation: "निकाला गया माल लागत पर दर्ज होता है और क्रय को कम करता है; यह विक्रय नहीं है, इसलिए विक्रय खाते को जमा नहीं किया जाता।" },
  "s12acc-b-006": { stem: "नए उत्पाद के प्रचार के लिए ₹3,000 लागत का माल निःशुल्क नमूने के रूप में बाँटा गया। नाम किया जाने वाला खाता है:", options: ["क्रय खाता","विज्ञापन खाता","विक्रय खाता","आहरण खाता"], explanation: "निःशुल्क नमूने प्रचार व्यय हैं: विज्ञापन खाता नाम, क्रय खाते से ₹3,000।" },
  "s12acc-b-007": { stem: "निम्नलिखित में से कौन-सी अशुद्धि तलपट के मिलान को प्रभावित नहीं करती?", options: ["क्रय बही का योग ₹500 कम लगाया गया","ग्राहक के खाते में नाम की राशि जमा पक्ष में खतौनी हुई","फर्नीचर का क्रय, क्रय खाते में नाम किया गया","राशि एक खाते में खतौनी हुई, दूसरे में नहीं"], explanation: "सैद्धांतिक अशुद्धि में सही राशि सही पक्ष में, परंतु गलत वर्ग के खाते में लिखी जाती है, अतः नाम और जमा बराबर रहते हैं। शेष तीनों एकपक्षीय अशुद्धियाँ हैं।" },
  "s12acc-b-008": { stem: "क्रय बही में दर्ज किया जाता है:", options: ["माल का सभी क्रय, नकद और उधार","केवल माल का नकद क्रय","स्थायी परिसंपत्तियों का उधार क्रय","पुनर्विक्रय हेतु माल का उधार क्रय"], explanation: "केवल व्यापारिक माल का उधार क्रय क्रय बही में जाता है; नकद क्रय रोकड़ बही में और परिसंपत्तियों का उधार क्रय मुख्य रोज़नामचे में दर्ज होता है।" },
  "s12acc-b-009": { stem: "रोकड़ बही ₹24,000 का नाम शेष दिखाती है। जारी किए गए परंतु भुगतान हेतु प्रस्तुत न हुए चेक ₹6,000; जमा किए गए परंतु संग्रहित न हुए चेक ₹4,500; ₹300 बैंक प्रभार रोकड़ बही में दर्ज नहीं। पासबुक के अनुसार शेष है:", options: ["₹25,200","₹22,200","₹25,800","₹21,300"], explanation: "24,000 + 6,000 (अप्रस्तुत) − 4,500 (असंग्रहित) − 300 (प्रभार) = ₹25,200 (पासबुक में जमा शेष)।" },
  "s12acc-b-010": { stem: "एक मशीन ₹2,00,000 में खरीदी गई और इसकी स्थापना पर ₹20,000 व्यय हुए। इसका अनुमानित अवशिष्ट मूल्य ₹20,000 और उपयोगी जीवन 10 वर्ष है। सरल रेखा पद्धति से वार्षिक मूल्यह्रास है:", options: ["₹18,000","₹20,000","₹22,000","₹24,000"], explanation: "मूल्यह्रास योग्य लागत में स्थापना व्यय शामिल है: (2,00,000 + 20,000 − 20,000)/10 = ₹20,000।" },
  "s12acc-b-011": { stem: "₹1,00,000 लागत की मशीन पर क्रमागत ह्रास (WDV) पद्धति से 10% वार्षिक मूल्यह्रास लगाया जाता है। तीसरे वर्ष का मूल्यह्रास है:", options: ["₹10,000","₹9,000","₹8,100","₹7,290"], explanation: "वर्ष 1: 10,000 (शेष 90,000); वर्ष 2: 9,000 (शेष 81,000); वर्ष 3: 81,000 का 10% = ₹8,100।" },
  "s12acc-b-012": { stem: "₹8,000 में क्रय किया गया फर्नीचर गलती से क्रय खाते में नाम कर दिया गया। सुधार प्रविष्टि है:", options: ["क्रय खाता नाम, फर्नीचर खाते से ₹8,000","फर्नीचर खाता नाम, उचन्त खाते से ₹8,000","उचन्त खाता नाम, क्रय खाते से ₹8,000","फर्नीचर खाता नाम, क्रय खाते से ₹8,000"], explanation: "यह सैद्धांतिक अशुद्धि है जो दो खातों को समान रूप से प्रभावित करती है, अतः उचन्त खाते की आवश्यकता नहीं: फर्नीचर खाता नाम, क्रय खाता जमा।" },
  "s12acc-b-013": { stem: "निम्नलिखित में से किस अशुद्धि का सुधार उचन्त खाते के माध्यम से होगा?", options: ["विक्रय बही का योग ₹1,000 कम लगाया गया","₹1,000 का उधार विक्रय विक्रय बही में पूरी तरह छूट गया","₹1,000 की मरम्मत मशीनरी खाते में नाम की गई","राम को चुकाए ₹1,000 श्याम के खाते में नाम किए गए"], explanation: "विक्रय बही का कम योग केवल विक्रय खाते के जमा पक्ष को कम करता है, यह एकपक्षीय अशुद्धि है। शेष दोनों पक्षों को समान रूप से प्रभावित करती हैं।" },
  "s12acc-b-014": { stem: "10 मार्च 2025 को लिखा गया एक विनिमय विपत्र तिथि के तीन माह बाद देय है। इसकी परिपक्वता तिथि है:", options: ["10 जून 2025","13 जून 2025","12 जून 2025","11 जून 2025"], explanation: "10 मार्च के तीन माह बाद 10 जून है; तीन अनुग्रह दिवस जोड़ने पर 13 जून 2025।" },
  "s12acc-b-015": { stem: "विनिमय विपत्र को स्वीकार करने वाला और परिपक्वता पर भुगतान के लिए उत्तरदायी पक्ष है:", options: ["लेखक","आदाता","आदेशिती (देनदार)","पृष्ठांकिती"], explanation: "लेखक विपत्र लिखता है, आदेशिती उसे स्वीकार करता है और परिपक्वता पर भुगतान करता है, तथा आदाता भुगतान प्राप्त करता है।" },
  "s12acc-b-016": { stem: "वर्ष के अंत में अदत्त मज़दूरी अंतिम खातों में इस प्रकार दिखाई जाती है:", options: ["व्यापार खाते में मज़दूरी से घटाई जाती है और चालू परिसंपत्ति के रूप में दिखाई जाती है","केवल लाभ-हानि खाते में मज़दूरी में जोड़ी जाती है","केवल चालू देयता के रूप में दिखाई जाती है","व्यापार खाते में मज़दूरी में जोड़ी जाती है और चालू देयता के रूप में दिखाई जाती है"], explanation: "समायोजन का सदैव दोहरा प्रभाव होता है: व्यय बढ़ता है (मज़दूरी प्रत्यक्ष व्यय है, अतः व्यापार खाते में) और अदत्त राशि देयता होती है।" },
  "s12acc-b-017": { stem: "1 जुलाई 2024 से आरंभ वर्ष के लिए ₹12,000 बीमा प्रीमियम चुकाया गया। खाते 31 मार्च 2025 को बंद होते हैं। लाभ-हानि खाते में चार्ज की जाने वाली राशि है:", options: ["₹9,000","₹12,000","₹3,000","₹15,000"], explanation: "जुलाई से मार्च 9 माह है: 12,000 × 9/12 = ₹9,000। शेष ₹3,000 पूर्वदत्त बीमा है, जो चालू परिसंपत्ति है।" },
  "s12acc-b-018": { stem: "एक फर्म परिणामों की तुलनीयता बनाए रखने के लिए वर्ष-प्रति-वर्ष मूल्यह्रास की क्रमागत ह्रास पद्धति अपनाती है। यह किसका पालन है?", options: ["सारता की अवधारणा","एकरूपता (सुसंगतता) की अवधारणा","आगम प्राप्ति की अवधारणा","उपार्जन की अवधारणा"], explanation: "एकरूपता की अवधारणा के अनुसार एक अवधि से दूसरी अवधि में समान लेखांकन नीतियाँ अपनाई जाती हैं, ताकि अंतर-अवधि तुलना सार्थक हो।" },
  "s12acc-b-019": { stem: "अभिकथन (A): तलपट का मिलान लेखा पुस्तकों की शुद्धता का निर्णायक प्रमाण नहीं है।\nकारण (R): तलपट खाता बही के खातों के शेषों से तैयार किया जाता है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"], explanation: "दोनों कथन सत्य हैं, परंतु A इसलिए सत्य है क्योंकि कुछ अशुद्धियाँ (लोप, सैद्धांतिक, क्षतिपूरक) योग को प्रभावित नहीं करतीं; R केवल तलपट बनाने की विधि बताता है।" },
  "s12acc-b-020": { stem: "निम्नलिखित में से कौन-सा लेन-देन परिसंपत्तियों के कुल योग को अपरिवर्तित रखता है?", options: ["उधार माल का क्रय","अतिरिक्त पूँजी के रूप में नकद लाना","नकद फर्नीचर का क्रय","लेनदार को नकद भुगतान"], explanation: "नकद फर्नीचर खरीदने पर एक परिसंपत्ति (रोकड़) के स्थान पर दूसरी (फर्नीचर) आती है। उधार क्रय और अतिरिक्त पूँजी परिसंपत्तियाँ बढ़ाते हैं; लेनदार को भुगतान उन्हें घटाता है।" },
  "s12acc-p-001": { stem: "एक तलपट का मिलान नहीं हुआ। बाद में ये अशुद्धियाँ मिलीं: (i) विक्रय बही का योग ₹1,000 कम लगाया गया; (ii) ₹800 क्रय वापसी आपूर्तिकर्ता के खाते में खतौनी हुई, परंतु क्रय वापसी खाते में नहीं; (iii) ₹500 मरम्मत भवन खाते में नाम की गई; (iv) ₹200 दी गई छूट ग्राहक के खाते में जमा की गई, परंतु छूट खाते में नाम नहीं की गई। तलपट का अंतर, जो उचन्त खाते में ले जाया गया, था:", options: ["जमा पक्ष में ₹1,800","जमा पक्ष में ₹2,300","नाम पक्ष में ₹1,600","जमा पक्ष में ₹1,600"], explanation: "जमा पक्ष 1,000 + 800 = 1,800 कम; नाम पक्ष 200 कम; (iii) का कोई प्रभाव नहीं। शुद्ध रूप से जमा पक्ष ₹1,600 कम है, अतः उचन्त खाता जमा पक्ष में ₹1,600 से दिखेगा।" },
  "s12acc-p-002": { stem: "1 अप्रैल 2022 को ₹2,00,000 में खरीदी गई मशीन पर क्रमागत ह्रास पद्धति से 20% वार्षिक मूल्यह्रास लगाया जाता है। 2023–24 का मूल्यह्रास लगाने के बाद 31 मार्च 2024 को इसे ₹1,20,000 में बेचा गया। बिक्री का परिणाम है:", options: ["हानि ₹8,000","लाभ ₹8,000","हानि ₹20,000","न लाभ न हानि"], explanation: "पुस्तक मूल्य: 2,00,000 − 40,000 = 1,60,000; 1,60,000 − 32,000 = 1,28,000। ₹1,20,000 में बिक्री पर ₹8,000 की हानि। 'न लाभ न हानि' केवल लागत पर 20% सरल रेखा पद्धति में होता।" },
  "s12acc-p-003": { stem: "इन कथनों पर विचार कीजिए:\nI. क्रमागत ह्रास पद्धति में परिसंपत्ति का पुस्तक मूल्य कभी शून्य नहीं होता।\nII. सरल रेखा पद्धति में मूल्यह्रास की राशि प्रति वर्ष समान रहती है।\nIII. क्रमागत ह्रास पद्धति में मूल्यह्रास प्रति वर्ष मूल लागत पर लगाया जाता है।\nइनमें से कौन-सा/से सही है/हैं?", options: ["केवल I और III","केवल I और II","केवल II और III","I, II और III"], explanation: "क्रमागत ह्रास पद्धति में घटते शेष पर स्थिर दर लगती है, अतः शेष कभी शून्य नहीं होता और मूल्यह्रास प्रति वर्ष घटता है; III सरल रेखा पद्धति का वर्णन है।" },
  "s12acc-p-004": { stem: "पासबुक ₹15,000 का अधिविकर्ष दिखाती है। जमा किए गए परंतु जमा न हुए चेक ₹4,000; जारी परंतु प्रस्तुत न हुए चेक ₹6,500; बैंक द्वारा नाम किया गया ₹700 अधिविकर्ष ब्याज, जो रोकड़ बही में दर्ज नहीं है। रोकड़ बही के अनुसार शेष है:", options: ["जमा शेष ₹13,200","नाम शेष ₹16,800","जमा शेष ₹16,800","जमा शेष ₹18,200"], explanation: "अधिविकर्ष (−15,000) से आरंभ: + 4,000 असंग्रहित चेक, − 6,500 अप्रस्तुत चेक, + 700 ब्याज जो रोकड़ बही में नहीं = −16,800, अर्थात ₹16,800 का जमा (अधिविकर्ष) शेष। उल्टी जाँच: −16,800 − 700 + 6,500 − 4,000 = −15,000।" },
  "s12acc-p-005": { stem: "तलपट: देनदार ₹82,000; अशोध्य ऋण ₹1,500; संदिग्ध ऋणों के लिए प्रावधान ₹3,000। समायोजन: अतिरिक्त अशोध्य ऋण ₹2,000; देनदारों पर 5% संदिग्ध ऋण प्रावधान रखना है। अशोध्य एवं संदिग्ध ऋणों के लिए लाभ-हानि खाते में कुल चार्ज राशि है:", options: ["₹7,500","₹4,600","₹3,500","₹4,500"], explanation: "नया प्रावधान = (82,000 − 2,000) का 5% = 4,000। चार्ज = 1,500 + 2,000 + 4,000 − 3,000 (पुराना प्रावधान) = ₹4,500। ₹4,600 में गलती से ₹82,000 का 5% लिया गया है।" },
  "s12acc-p-006": { stem: "जब अंतिम स्टॉक तलपट के भीतर दिखाई दे (क्रय पहले ही उसके लिए समायोजित हो चुका हो), तो अंतिम खातों में यह दिखाया जाता है:", options: ["केवल तुलन पत्र के परिसंपत्ति पक्ष में","केवल व्यापार खाते के जमा पक्ष में","व्यापार खाते के जमा पक्ष और तुलन पत्र दोनों में","व्यापार खाते के नाम पक्ष में"], explanation: "यदि अंतिम स्टॉक तलपट में है तो समायोजित क्रय उसे पहले से दर्शाता है; व्यापार खाते में फिर से जमा करने पर दोहरी गणना होगी, अतः यह केवल तुलन पत्र में जाता है।" },
  "s12acc-p-007": { stem: "प्रबंधक का कमीशन चार्ज करने से पहले शुद्ध लाभ ₹2,20,000 है। प्रबंधक ऐसे कमीशन को चार्ज करने के बाद के शुद्ध लाभ का 10% कमीशन पाने का अधिकारी है। कमीशन है:", options: ["₹22,000","₹20,000","₹24,200","₹18,000"], explanation: "कमीशन = 2,20,000 × 10/110 = ₹20,000 (जाँच: 2,00,000 का 10% = 20,000)। ₹22,000 कमीशन से पहले के लाभ का 10% होता।" },
  "s12acc-p-008": { stem: "अनिल ने बिमल पर ₹20,000 का विपत्र लिखा और उसे अपने बैंक से ₹19,600 में भुना लिया। परिपक्वता पर विपत्र अनादृत हो गया और बैंक ने ₹100 निकराई व्यय चुकाए। अनादरण पर अनिल की पुस्तकों में प्रविष्टि है:", options: ["बिमल का खाता नाम, प्राप्य विपत्र खाते से ₹20,000","बैंक खाता नाम, बिमल के खाते से ₹19,600","बिमल का खाता नाम, बैंक खाते से ₹20,100","बिमल का खाता नाम ₹20,000, निकराई व्यय खाता नाम ₹100, प्राप्य विपत्र खाते से ₹20,100"], explanation: "भुनाया गया विपत्र अनिल के पास नहीं है; बैंक उससे पूरा अंकित मूल्य और निकराई व्यय वसूलता है, और वह बिमल से: बिमल नाम 20,100, बैंक जमा 20,100।" },
  "s12acc-p-009": { stem: "कमल द्वारा स्वीकृत ₹30,000 का विपत्र आज देय है। कमल भुगतान नहीं कर सकता और 12% वार्षिक ब्याज सहित तीन माह के लिए नवीनीकरण का अनुरोध करता है। यदि ब्याज नए विपत्र में शामिल हो, तो नए विपत्र की राशि है:", options: ["₹33,600","₹30,300","₹31,200","₹30,900"], explanation: "ब्याज = 30,000 × 12/100 × 3/12 = ₹900, अतः नया विपत्र ₹30,900 का। ₹33,600 में गलती से पूरे वर्ष का ब्याज लिया गया है।" },
  "s12acc-p-010": { stem: "अभिकथन (A): उधार विक्रय का आगम उसी अवधि में मान्य किया जाता है जिसमें माल बेचा गया, भले ही नकद अगली अवधि में मिले।\nकारण (R): आगम प्राप्ति (आगम मान्यता) की अवधारणा के अनुसार आगम तब प्राप्त माना जाता है जब उसे प्राप्त करने का वैधानिक अधिकार उत्पन्न होता है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"], explanation: "दोनों सत्य हैं और R, A की व्याख्या करता है: भुगतान प्राप्त करने का वैधानिक अधिकार विक्रय के समय उत्पन्न होता है, अतः आगम उसी अवधि का है, नकद चाहे जब आए।" },
  "s12acc-p-011": { stem: "सूची I (अवधारणा) को सूची II (उदाहरण) से सुमेलित कीजिए।\nसूची I: A. व्यावसायिक इकाई  B. मुद्रा मापन  C. सारता  D. एकरूपता\nसूची II: 1. ₹150 का स्टेपलर वर्षों चलने पर भी व्यय में लिखा जाता है  2. स्टॉक मूल्यांकन की एक ही विधि प्रति वर्ष अपनाई जाती है  3. स्वामी की पूँजी व्यवसाय की देयता के रूप में दिखाई जाती है  4. कर्मचारियों का कौशल पुस्तकों में दर्ज नहीं होता", options: ["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"], explanation: "इकाई: व्यवसाय स्वामी से पृथक है (पूँजी उसकी देय है)। मुद्रा मापन: केवल मुद्रा में मापनीय मदें दर्ज होती हैं। सारता: नगण्य मदें व्यय में लिखी जाती हैं। एकरूपता: प्रति वर्ष एक ही नीति।" },
  "s12acc-p-012": { stem: "2023–24 की पुस्तकें बंद होने के बाद पता चला कि ₹5,000 की मरम्मत मशीनरी खाते में नाम कर दी गई थी। 2024–25 में की जाने वाली सुधार प्रविष्टि है:", options: ["मरम्मत खाता नाम, मशीनरी खाते से ₹5,000","लाभ-हानि समायोजन खाता नाम, मशीनरी खाते से ₹5,000","मशीनरी खाता नाम, लाभ-हानि समायोजन खाते से ₹5,000","उचन्त खाता नाम, मशीनरी खाते से ₹5,000"], explanation: "पिछले वर्ष के नाममात्र खाते बंद हो चुके हैं, अतः पिछले वर्ष के लाभ का सुधार लाभ-हानि समायोजन खाते से होता है; मशीनरी अधिक दिखाई गई थी, अतः उसे जमा किया जाता है।" },
  "s12acc-p-013": { stem: "₹5,00,000 लागत की मशीनरी 1 अप्रैल 2021 को खरीदी गई और मूल्यह्रास प्रावधान खाते का प्रयोग करते हुए सरल रेखा पद्धति से 10% वार्षिक मूल्यह्रास लगाया जाता है। 1 अप्रैल 2024 को ₹1,00,000 लागत का एक भाग ₹60,000 में बेचा गया। बिक्री का परिणाम है:", options: ["हानि ₹40,000","लाभ ₹10,000","हानि ₹10,000","हानि ₹20,000"], explanation: "उस भाग पर संचित मूल्यह्रास = 3 वर्ष × 10,000 = 30,000; पुस्तक मूल्य = 70,000; ₹60,000 में बिक्री पर ₹10,000 हानि। ₹20,000 केवल दो वर्ष गिनने पर आता।" },
  "s12acc-p-014": { stem: "₹20,000 लागत का माल ₹25,000 में उधार बेचा गया। लेखांकन समीकरण पर प्रभाव है:", options: ["परिसंपत्तियाँ ₹25,000 बढ़ती हैं और पूँजी ₹25,000 बढ़ती है","परिसंपत्तियाँ ₹25,000 बढ़ती हैं और देयताएँ ₹5,000 बढ़ती हैं","परिसंपत्तियाँ अपरिवर्तित रहती हैं और पूँजी ₹5,000 बढ़ती है","परिसंपत्तियाँ ₹5,000 बढ़ती हैं और पूँजी ₹5,000 बढ़ती है"], explanation: "स्टॉक 20,000 घटता है और देनदार 25,000 बढ़ते हैं, अर्थात परिसंपत्तियों में शुद्ध 5,000 की वृद्धि; 5,000 का लाभ पूँजी में जुड़ता है।" },
  "s12acc-p-015": { stem: "₹40,000 सूची मूल्य का माल किरण को 10% व्यापारिक छूट और 2% नकद छूट पर बेचा गया। किरण ने देय राशि का आधा तुरंत चुका दिया। दी गई छूट खाते में नाम की जाने वाली राशि है:", options: ["₹360","₹720","₹4,000","₹4,360"], explanation: "बीजक मूल्य = 40,000 − 4,000 = 36,000। तुरंत चुकाया आधा = 18,000, जिस पर 2% नकद छूट = ₹360। व्यापारिक छूट पुस्तकों में कभी दर्ज नहीं होती।" },
  "s12acc-p-016": { stem: "1 अप्रैल 2024 को एकल व्यापारी की पूँजी ₹4,00,000 थी। उसने 1 अक्टूबर 2024 को ₹1,00,000 अतिरिक्त पूँजी लगाई। पूँजी पर 5% वार्षिक ब्याज दिया जाता है। 31 मार्च 2025 को समाप्त वर्ष के लिए पूँजी पर ब्याज है:", options: ["₹25,000","₹22,500","₹20,000","₹21,250"], explanation: "पूरे वर्ष के लिए 4,00,000 × 5% = 20,000, तथा छह माह के लिए 1,00,000 × 5% × 6/12 = 2,500: कुल ₹22,500।" },
  "s12acc-p-017": { stem: "प्रारंभिक स्टॉक ₹40,000; क्रय ₹2,60,000; आवक गाड़ी भाड़ा ₹6,000; मज़दूरी ₹14,000; विक्रय ₹4,00,000; विक्रय वापसी ₹10,000; जावक गाड़ी भाड़ा ₹5,000; अंतिम स्टॉक ₹50,000। सकल लाभ है:", options: ["₹1,15,000","₹1,30,000","₹1,20,000","₹1,34,000"], explanation: "बेचे गए माल की लागत = 40,000 + 2,60,000 + 6,000 + 14,000 − 50,000 = 2,70,000। शुद्ध विक्रय = 3,90,000। सकल लाभ = ₹1,20,000। जावक गाड़ी भाड़ा विक्रय व्यय है (लाभ-हानि खाता), व्यापार खाते की मद नहीं।" },
  "s12acc-p-018": { stem: "₹30,000 लागत का माल आग से नष्ट हो गया। बीमा कंपनी ने ₹22,000 का दावा स्वीकार किया, जो अभी प्राप्त नहीं हुआ है। अंतिम खातों में कौन-सा व्यवहार सही है?", options: ["₹22,000 व्यापार खाते में नाम और ₹8,000 लाभ-हानि खाते में जमा","₹8,000 व्यापार खाते में जमा और ₹22,000 चालू देयता के रूप में","केवल ₹8,000 लाभ-हानि खाते में नाम; व्यापार खाते में कोई प्रविष्टि नहीं","₹30,000 व्यापार खाते में जमा, ₹8,000 लाभ-हानि खाते में नाम, ₹22,000 चालू परिसंपत्ति के रूप में"], explanation: "नष्ट माल की पूरी लागत व्यापार खाते से हटाई जाती है (जमा ₹30,000); न वसूल हुए ₹8,000 असामान्य हानि के रूप में लाभ-हानि खाते में; स्वीकृत दावा प्राप्य चालू परिसंपत्ति है।" },
  "s12acc-p-019": { stem: "रमेश को ₹4,500 का उधार विक्रय विक्रय बही में सही दर्ज हुआ, परंतु राकेश के खाते के नाम पक्ष में खतौनी हो गई। यह अशुद्धि है:", options: ["लेखन (क्रियात्मक) अशुद्धि, जो तलपट को प्रभावित नहीं करती","सैद्धांतिक अशुद्धि, जो तलपट को प्रभावित नहीं करती","लेखन अशुद्धि, जिससे तलपट का मिलान नहीं होता","लोप की अशुद्धि, जिससे तलपट का मिलान नहीं होता"], explanation: "उसी वर्ग के गलत व्यक्तिगत खाते में, सही पक्ष में खतौनी लेखन अशुद्धि है; नाम और जमा के योग बराबर रहते हैं।" },
  "s12acc-p-020": { stem: "तलपट में दिखाया गया ₹36,000 प्राप्त किराया अगले लेखा वर्ष के ₹6,000 सहित है। अंतिम खातों में:", options: ["₹36,000 लाभ-हानि खाते में जमा और ₹6,000 चालू परिसंपत्ति के रूप में","₹30,000 लाभ-हानि खाते में जमा और ₹6,000 देयता (अग्रिम प्राप्त आय) के रूप में","₹42,000 लाभ-हानि खाते में जमा और ₹6,000 देयता के रूप में","₹30,000 लाभ-हानि खाते में जमा और ₹6,000 चालू परिसंपत्ति के रूप में"], explanation: "केवल चालू अवधि की आय जमा होती है (36,000 − 6,000); अग्रिम राशि के बदले किरायेदार को सेवा देनी है, अतः यह चालू देयता है।" },
  "s12acc-b-021": { stem: "साझेदारी संलेख के अभाव में, फर्म को ऋण देने वाला साझेदार उस पर किस दर से ब्याज पाने का अधिकारी है?", options: ["9% वार्षिक","12% वार्षिक","6% वार्षिक","कोई ब्याज नहीं"], explanation: "भारतीय साझेदारी अधिनियम, 1932 की धारा 13(d) के अनुसार समझौते के अभाव में साझेदार के ऋण पर 6% वार्षिक ब्याज मिलता है। इसके विपरीत, पूँजी पर ब्याज नहीं मिलता।" },
  "s12acc-b-022": { stem: "अभिकथन (A): साझेदारी संलेख के अभाव में, फर्म के व्यवसाय में अधिक समय देने वाला साझेदार वेतन पाने का अधिकारी है।\nकारण (R): भारतीय साझेदारी अधिनियम, 1932 के अनुसार, साझेदारों के बीच समझौता न हो तो किसी साझेदार को व्यवसाय में भाग लेने के लिए पारिश्रमिक का अधिकार नहीं है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"], explanation: "R सामान्य नियम को सही बताता है, जिससे A असत्य है: समझौते के बिना कोई वेतन देय नहीं, चाहे साझेदार कितना भी समय दे।" },
  "s12acc-b-023": { stem: "एक साझेदार ने पूरे वर्ष प्रत्येक माह के आरंभ में ₹5,000 का आहरण किया। आहरण पर 10% वार्षिक ब्याज लगाया जाता है। आहरण पर ब्याज है:", options: ["₹3,000","₹2,750","₹6,000","₹3,250"], explanation: "कुल आहरण 60,000; प्रत्येक माह के आरंभ में आहरण पर औसत अवधि 6.5 माह: 60,000 × 10% × 6.5/12 = ₹3,250। माह के अंत में आहरण पर 5.5 माह (₹2,750)।" },
  "s12acc-b-024": { stem: "1 अप्रैल 2024 को एक साझेदार की पूँजी ₹3,00,000 थी और उसने 1 जनवरी 2025 को ₹60,000 अतिरिक्त पूँजी लगाई। पूँजी पर 8% वार्षिक ब्याज दिया जाता है। 31 मार्च 2025 को समाप्त वर्ष के लिए उसका पूँजी पर ब्याज है:", options: ["₹25,200","₹24,000","₹28,800","₹26,400"], explanation: "3,00,000 × 8% = 24,000, तथा जनवरी से मार्च के लिए 60,000 × 8% × 3/12 = 1,200: कुल ₹25,200।" },
  "s12acc-b-025": { stem: "साझेदारों के पूँजी खाते रखने की स्थायी पूँजी पद्धति में:", options: ["सभी समायोजन सीधे पूँजी खातों में किए जाते हैं","आहरण, पूँजी पर ब्याज और लाभ का हिस्सा साझेदारों के चालू खातों में दर्ज होते हैं","साझेदारों के पूँजी खाते नाम शेष दिखा सकते हैं","प्रत्येक साझेदार का केवल एक खाता रखा जाता है"], explanation: "स्थायी पूँजी पद्धति में प्रत्येक साझेदार के दो खाते होते हैं; पूँजी खाता केवल पूँजी जोड़ने या निकालने पर बदलता है और अन्य सभी मदें चालू खाते में जाती हैं।" },
  "s12acc-b-026": { stem: "एक फर्म के पिछले चार वर्षों के लाभ ₹80,000, ₹1,00,000, ₹90,000 और ₹1,30,000 थे। ख्याति का मूल्यांकन औसत लाभ के तीन वर्षों के क्रय पर करना है। ख्याति है:", options: ["₹4,00,000","₹3,90,000","₹3,00,000","₹2,70,000"], explanation: "औसत लाभ = 4,00,000/4 = 1,00,000; ख्याति = 1,00,000 × 3 = ₹3,00,000।" },
  "s12acc-b-027": { stem: "एक फर्म की नियोजित पूँजी ₹5,00,000, प्रत्याय की सामान्य दर 10% और औसत लाभ ₹80,000 है। अधिलाभ के दो वर्षों के क्रय पर ख्याति है:", options: ["₹1,60,000","₹30,000","₹1,00,000","₹60,000"], explanation: "सामान्य लाभ = 5,00,000 का 10% = 50,000; अधिलाभ = 80,000 − 50,000 = 30,000; ख्याति = 30,000 × 2 = ₹60,000।" },
  "s12acc-b-028": { stem: "A और B लाभ 3 : 2 में बाँटते हैं। C का प्रवेश होता है और A, B तथा C का नया लाभ विभाजन अनुपात 5 : 3 : 2 है। A और B का त्याग अनुपात है:", options: ["1 : 1","3 : 2","5 : 3","2 : 1"], explanation: "पुराने हिस्से 6/10 और 4/10; नए हिस्से 5/10 और 3/10। प्रत्येक 1/10 का त्याग करता है, अतः अनुपात 1 : 1।" },
  "s12acc-b-029": { stem: "नए साझेदार के प्रवेश पर परिसंपत्तियों और देयताओं के पुनर्मूल्यांकन का लाभ:", options: ["नए साझेदार सहित सभी साझेदारों के खातों में नए अनुपात में जमा किया जाता है","पुराने साझेदारों के पूँजी खातों में पुराने लाभ अनुपात में जमा किया जाता है","पुराने साझेदारों के खातों में त्याग अनुपात में जमा किया जाता है","सामान्य संचय में हस्तांतरित किया जाता है"], explanation: "मूल्यों में परिवर्तन नए साझेदार के आने से पहले हुआ, अतः यह पुराने साझेदारों का है और उनके पुराने अनुपात में बँटता है।" },
  "s12acc-b-030": { stem: "A, B और C लाभ 2 : 2 : 1 में बाँटते हैं। C अवकाश ग्रहण करता है और A तथा B भविष्य के लाभ 3 : 2 में बाँटने का निर्णय करते हैं। A और B का लाभ अनुपात है:", options: ["1 : 1","3 : 2","A, C का पूरा हिस्सा प्राप्त करता है (1 : 0)","2 : 3"], explanation: "A: 3/5 − 2/5 = 1/5 का लाभ; B: 2/5 − 2/5 = 0। C का 1/5 हिस्सा अकेले A लेता है।" },
  "s12acc-b-031": { stem: "लाभ में 1/4 हिस्से वाले साझेदार की मृत्यु 30 जून 2024 को होती है। फर्म का लेखा वर्ष 1 अप्रैल से आरंभ होता है और मृत्यु की तिथि तक मृत साझेदार का लाभ का हिस्सा पिछले वर्ष के ₹1,20,000 लाभ के आधार पर निकालना है। उसका हिस्सा है:", options: ["₹10,000","₹30,000","₹22,500","₹7,500"], explanation: "3 माह (अप्रैल से जून) का लाभ = 1,20,000 × 3/12 = 30,000; उसका 1/4 हिस्सा = ₹7,500।" },
  "s12acc-b-032": { stem: "फर्म के विघटन पर निम्नलिखित में से कौन-सा वसूली खाते में हस्तांतरित नहीं किया जाता?", options: ["फर्म को साझेदार का ऋण","व्यापारिक लेनदार","देय विपत्र","बैंक ऋण"], explanation: "बाह्य देयताएँ वसूली खाते में हस्तांतरित होती हैं, परंतु साझेदार के ऋण का निपटान बाहरी लोगों के भुगतान के बाद अलग से होता है।" },
  "s12acc-b-033": { stem: "भारतीय साझेदारी अधिनियम, 1932 की धारा 48 के अनुसार विघटन पर वसूल राशि इस क्रम में प्रयोग की जाती है:", options: ["साझेदारों की पूँजी, फिर साझेदारों के ऋण, फिर बाह्य ऋण","बाह्य ऋण, फिर साझेदारों के ऋण, फिर साझेदारों की पूँजी","साझेदारों के ऋण, फिर बाह्य ऋण, फिर साझेदारों की पूँजी","बाह्य ऋण, फिर साझेदारों की पूँजी, फिर साझेदारों के ऋण"], explanation: "पहले तीसरे पक्षों के ऋण, फिर साझेदारों के अग्रिम (पूँजी से भिन्न), और उसके बाद ही प्रत्येक साझेदार की पूँजी।" },
  "s12acc-b-034": { stem: "कंपनी अधिनियम, 2013 की धारा 52 के अनुसार प्रतिभूति प्रीमियम खाते का प्रयोग किसके लिए नहीं किया जा सकता?", options: ["पूर्णदत्त बोनस अंश जारी करने के लिए","कंपनी के प्रारंभिक व्यय अपलिखित करने के लिए","अंशधारकों को लाभांश देने के लिए","ऋणपत्रों के शोधन पर देय प्रीमियम का प्रावधान करने के लिए"], explanation: "धारा 52 प्रतिभूति प्रीमियम के अनुमत उपयोग बताती है; लाभांश के रूप में वितरण उनमें नहीं है, क्योंकि प्रीमियम पूँजीगत प्रकृति का है।" },
  "s12acc-b-035": { stem: "₹10 वाले 1,000 अंश, जिन पर प्रति अंश ₹8 की याचना हो चुकी थी, हरण कर लिए गए। अंशधारक ने आवेदन और आबंटन पर प्रति अंश ₹5 चुकाए थे, परंतु ₹3 की प्रथम याचना नहीं चुकाई। अंश हरण खाते में जमा की गई राशि है:", options: ["₹8,000","₹3,000","₹10,000","₹5,000"], explanation: "अंश पूँजी याचित राशि (₹8,000) से नाम होती है; अदत्त याचना ₹3,000 याचना खाते में और प्राप्त राशि ₹5,000 अंश हरण खाते में जमा होती है।" },
  "s12acc-b-036": { stem: "₹10 वाले 100 पूर्ण याचित अंश, जिन पर प्रति अंश ₹6 प्राप्त हुए थे, हरण कर लिए गए। उन्हें ₹8 प्रति अंश पर पूर्णदत्त के रूप में पुनर्निर्गमित किया गया। पूँजी संचय में हस्तांतरित राशि है:", options: ["₹400","₹600","₹200","₹800"], explanation: "हरण राशि = 100 × 6 = 600; पुनर्निर्गमन पर बट्टा = 100 × 2 = 200; शेष 600 − 200 = ₹400 पूँजी संचय में जाता है।" },
  "s12acc-b-037": { stem: "एक कंपनी ने ₹100 वाले 1,000 ऋणपत्र 5% बट्टे पर जारी किए, जिनका शोधन 10% प्रीमियम पर होगा। ऋणपत्रों के निर्गमन पर हानि है:", options: ["₹5,000","₹15,000","₹10,000","₹1,05,000"], explanation: "निर्गमन पर बट्टा 1,000 × 5 = 5,000 तथा शोधन पर देय प्रीमियम 1,000 × 10 = 10,000: निर्गमन पर कुल हानि ₹15,000।" },
  "s12acc-b-038": { stem: "एक कंपनी ने 50,000 अंशों के लिए आवेदन आमंत्रित किए, जिन पर आवेदन के साथ प्रति अंश ₹3 देय थे। 70,000 अंशों के लिए आवेदन प्राप्त हुए और सभी आवेदकों को आनुपातिक आबंटन किया गया। आबंटन में समायोजन हेतु उपलब्ध अतिरिक्त आवेदन राशि है:", options: ["₹2,10,000","₹1,50,000","₹60,000","₹20,000"], explanation: "अतिरिक्त आवेदित अंश = 20,000; अतिरिक्त राशि = 20,000 × ₹3 = ₹60,000, जो देय आबंटन राशि में समायोजित होती है।" },
  "s12acc-p-021": { stem: "A, B और C लाभ 2 : 2 : 1 में बाँटते हैं। C को ₹30,000 न्यूनतम लाभ की गारंटी है और कोई कमी A तथा B अपने आपसी अनुपात में वहन करेंगे। फर्म का लाभ ₹1,20,000 है। A का अंतिम लाभ का हिस्सा है:", options: ["₹48,000","₹42,000","₹44,000","₹45,000"], explanation: "C का हिस्सा = 1,20,000 × 1/5 = 24,000; कमी 6,000, A और B बराबर (2 : 2) वहन करेंगे, 3,000 प्रत्येक। A = 48,000 − 3,000 = ₹45,000।" },
  "s12acc-p-022": { stem: "A और B लाभ 3 : 2 में बाँटते हैं और उनकी पूँजी ₹1,00,000 तथा ₹60,000 है। खाते बंद होने के बाद पता चला कि पूँजी पर 10% वार्षिक ब्याज छूट गया था। एकल समायोजन प्रविष्टि है:", options: ["B का पूँजी खाता नाम, A के पूँजी खाते से ₹400","A का पूँजी खाता नाम, B के पूँजी खाते से ₹400","B का पूँजी खाता नाम, A के पूँजी खाते से ₹4,000","लाभ-हानि समायोजन खाता नाम, A के पूँजी खाते से ₹10,000"], explanation: "देय ब्याज: A 10,000, B 6,000 (कुल 16,000)। इसे चार्ज करने पर लाभ के हिस्से 9,600 और 6,400 घटते। शुद्ध: A +400, B −400, अतः B नाम और A जमा ₹400।" },
  "s12acc-p-023": { stem: "एक फर्म का औसत लाभ ₹60,000 है। उद्योग में प्रत्याय की सामान्य दर 12% है और फर्म की नियोजित पूँजी ₹4,00,000 है। औसत लाभ के पूँजीकरण की पद्धति से ख्याति है:", options: ["₹5,00,000","₹1,00,000","₹12,000","₹1,20,000"], explanation: "पूँजीकृत मूल्य = 60,000 × 100/12 = 5,00,000; ख्याति = 5,00,000 − 4,00,000 = ₹1,00,000।" },
  "s12acc-p-024": { stem: "एक फर्म के तीन वर्षों के लाभ थे: वर्ष 1 ₹30,000, वर्ष 2 ₹45,000, वर्ष 3 ₹60,000। वर्षों को क्रमशः 1, 2 और 3 भार दिए गए हैं। भारित औसत लाभ के दो वर्षों के क्रय पर ख्याति है:", options: ["₹90,000","₹50,000","₹1,00,000","₹1,35,000"], explanation: "भारित औसत = (30,000 × 1 + 45,000 × 2 + 60,000 × 3)/6 = 3,00,000/6 = 50,000; ख्याति = ₹1,00,000। साधारण औसत (45,000) से ₹90,000 आता।" },
  "s12acc-p-025": { stem: "A और B लाभ 3 : 2 में बाँटते हैं। C को 1/4 हिस्से के लिए प्रवेश दिया जाता है और वह ख्याति के प्रीमियम के रूप में ₹40,000 लाता है। A, B और C का नया अनुपात 2 : 1 : 1 है। प्रीमियम जमा किया जाता है:", options: ["A ₹24,000 और B ₹16,000","A ₹20,000 और B ₹20,000","A ₹26,667 और B ₹13,333","A ₹16,000 और B ₹24,000"], explanation: "त्याग: A 3/5 − 2/4 = 1/10; B 2/5 − 1/4 = 3/20। त्याग अनुपात 2 : 3, अतः A को 16,000 और B को 24,000। पुराना अनुपात 3 : 2 प्रयोग करना भ्रामक विकल्प है।" },
  "s12acc-p-026": { stem: "सभी समायोजनों के बाद A और B की पूँजी ₹1,00,000 प्रत्येक है। C को 1/3 हिस्से के लिए प्रवेश दिया जाता है और वह पूँजी के रूप में ₹1,50,000 लाता है, परंतु ख्याति के लिए अलग से कोई राशि नहीं। फर्म की छिपी ख्याति है:", options: ["₹1,00,000","₹1,50,000","₹50,000","₹4,50,000"], explanation: "अंतर्निहित कुल पूँजी = 1,50,000 × 3 = 4,50,000; वास्तविक कुल = 1,00,000 + 1,00,000 + 1,50,000 = 3,50,000; छिपी ख्याति = ₹1,00,000।" },
  "s12acc-p-027": { stem: "A, B और C लाभ 3 : 2 : 1 में बाँटते हैं। B अवकाश ग्रहण करता है और A तथा C भविष्य के लाभ 3 : 1 में बाँटेंगे। फर्म की ख्याति ₹60,000 आँकी गई है। B के ख्याति के हिस्से की प्रविष्टि है:", options: ["A का पूँजी खाता नाम ₹12,000, C का पूँजी खाता नाम ₹8,000, B के पूँजी खाते से ₹20,000","A का पूँजी खाता नाम ₹15,000, C का पूँजी खाता नाम ₹5,000, B के पूँजी खाते से ₹20,000","A का पूँजी खाता नाम ₹10,000, C का पूँजी खाता नाम ₹10,000, B के पूँजी खाते से ₹20,000","ख्याति खाता नाम, B के पूँजी खाते से ₹20,000"], explanation: "B का हिस्सा = 60,000 × 2/6 = 20,000। लाभ: A 3/4 − 3/6 = 1/4; C 1/4 − 1/6 = 1/12; लाभ अनुपात 3 : 1, अतः A 15,000 और C 5,000 वहन करेंगे।" },
  "s12acc-p-028": { stem: "विघटन पर ₹2,00,000 पुस्तक मूल्य की परिसंपत्तियाँ (रोकड़ के अतिरिक्त) और ₹50,000 के लेनदार वसूली खाते में हस्तांतरित किए गए। परिसंपत्तियों से ₹1,70,000 वसूल हुए, लेनदारों का निपटान ₹48,000 में हुआ और वसूली व्यय ₹2,000 थे। वसूली का परिणाम है:", options: ["हानि ₹28,000","हानि ₹32,000","हानि ₹30,000","लाभ ₹20,000"], explanation: "नाम पक्ष: 2,00,000 + 48,000 + 2,000 = 2,50,000। जमा पक्ष: 50,000 + 1,70,000 = 2,20,000। हानि = ₹30,000।" },
  "s12acc-p-029": { stem: "भारतीय साझेदारी अधिनियम, 1932 की धारा 37 के अनुसार, जब अवकाश ग्रहण करने वाले साझेदार की देय राशि का निपटान न हो और व्यवसाय उसी राशि से चलता रहे, तो अवकाश ग्रहण करने वाला साझेदार (या उसकी संपदा) अपने विकल्प पर पाने का अधिकारी है:", options: ["केवल देय राशि पर 12% वार्षिक ब्याज","केवल उस राशि के प्रयोग से अर्जित लाभ का हिस्सा","देय राशि पर 9% वार्षिक ब्याज, या निश्चित वेतन","देय राशि पर 6% वार्षिक ब्याज, या उस राशि के प्रयोग से अर्जित लाभ का हिस्सा"], explanation: "धारा 37 जाने वाले साझेदार को यह विकल्प देती है: संपत्ति में उसके हिस्से के प्रयोग से प्राप्त लाभ का अंश, या 6% वार्षिक ब्याज।" },
  "s12acc-p-030": { stem: "एक कंपनी ने ₹10 वाले 20,000 अंश ₹2 प्रीमियम पर जारी किए, देय: आवेदन पर ₹3, आबंटन पर ₹5 (प्रीमियम सहित) और शेष याचना पर। 30,000 अंशों के लिए आवेदन प्राप्त हुए और आनुपातिक आबंटन किया गया; अतिरिक्त आवेदन राशि आबंटन में समायोजित की गई। आबंटन पर प्राप्त नकद है:", options: ["₹70,000","₹1,00,000","₹40,000","₹60,000"], explanation: "आवेदन राशि 30,000 × 3 = 90,000, जिसमें से 60,000 की आवश्यकता; अतिरिक्त 30,000। देय आबंटन 20,000 × 5 = 1,00,000; प्राप्त नकद = 1,00,000 − 30,000 = ₹70,000।" },
  "s12acc-p-031": { stem: "₹10 वाले 200 अंश ₹12 प्रति अंश पर जारी किए गए, ₹2 प्रीमियम आबंटन के साथ देय था। एक अंशधारक ने केवल ₹3 प्रति अंश आवेदन राशि चुकाई और आबंटन (प्रीमियम सहित ₹5) तथा अंतिम याचना (₹4) नहीं चुकाई। उसके अंश हरण कर लिए गए। अंश पूँजी और प्रतिभूति प्रीमियम में क्रमशः नाम की गई राशियाँ हैं:", options: ["₹2,400 और शून्य","₹2,000 और ₹400","₹2,000 और शून्य","₹600 और ₹400"], explanation: "अंश पूँजी याचित अंकित मूल्य (200 × 10 = 2,000) से नाम होती है। प्रीमियम कभी प्राप्त नहीं हुआ, अतः प्रतिभूति प्रीमियम (200 × 2 = 400) भी नाम होता है; हरण खाता 600 से जमा होता है।" },
  "s12acc-p-032": { stem: "₹10 वाले 300 पूर्ण याचित अंश, जिन पर प्रति अंश ₹4 चुकाए गए थे, हरण कर लिए गए। इनमें से 200 अंश ₹7 प्रति अंश पर पूर्णदत्त के रूप में पुनर्निर्गमित किए गए। पूँजी संचय में हस्तांतरित राशि है:", options: ["₹800","₹600","₹200","₹400"], explanation: "पुनर्निर्गमित 200 अंशों पर हरण राशि = 200 × 4 = 800; दिया गया बट्टा = 200 × 3 = 600; पूँजी संचय = ₹200। शेष 100 अंशों के ₹400 अंश हरण खाते में रहते हैं।" },
  "s12acc-p-033": { stem: "बैंक ऋण के लिए समपार्श्विक प्रतिभूति के रूप में जारी ऋणपत्रों के बारे में कौन-सा कथन सही है?", options: ["इन पर कूपन दर से ब्याज देय होता है","बैंक के अतिरिक्त ऋणपत्रधारी भी लेनदार बन जाते हैं","इन्हें तुलन पत्र में गैर-चालू परिसंपत्तियों के अंतर्गत दिखाया जाता है","इन पर कोई ब्याज देय नहीं होता, और इन्हें ऋणपत्र उचन्त खाते द्वारा दर्ज किया जा सकता है या केवल टिप्पणी में दिखाया जा सकता है"], explanation: "समपार्श्विक ऋणपत्र केवल गौण प्रतिभूति हैं; बैंक ऋण पर ब्याज पाता है, ऋणपत्रों पर नहीं, और इन्हें या तो दर्ज ही नहीं किया जाता (टिप्पणी) या ऋणपत्र उचन्त खाते से दर्ज किया जाता है।" },
  "s12acc-p-034": { stem: "एक कंपनी ने ₹4,40,000 की परिसंपत्तियाँ खरीदीं और विक्रेता को ₹100 वाले 12% ऋणपत्र 10% प्रीमियम पर जारी करके भुगतान किया। जारी ऋणपत्रों की संख्या है:", options: ["4,000","4,400","4,840","3,960"], explanation: "निर्गम मूल्य = ₹110 प्रति ऋणपत्र; संख्या = 4,40,000/110 = 4,000।" },
  "s12acc-p-035": { stem: "एक साझेदार ने 1 जुलाई 2024 को ₹10,000, 1 अक्टूबर 2024 को ₹6,000 और 1 जनवरी 2025 को ₹4,000 का आहरण किया। आहरण पर 12% वार्षिक ब्याज लगाया जाता है और वर्ष 31 मार्च 2025 को समाप्त होता है। आहरण पर ब्याज है:", options: ["₹2,400","₹1,380","₹1,200","₹1,500"], explanation: "10,000 × 12% × 9/12 = 900; 6,000 × 12% × 6/12 = 360; 4,000 × 12% × 3/12 = 120। कुल ₹1,380।" },
  "s12acc-p-036": { stem: "A और B लाभ 3 : 2 में बाँटते हैं। वे भविष्य के लाभ बराबर बाँटने का निर्णय करते हैं। फर्म की ख्याति ₹50,000 आँकी गई है और ख्याति खाता नहीं खोला जाना है। समायोजन प्रविष्टि है:", options: ["A का पूँजी खाता नाम, B के पूँजी खाते से ₹5,000","B का पूँजी खाता नाम, A के पूँजी खाते से ₹10,000","B का पूँजी खाता नाम, A के पूँजी खाते से ₹5,000","ख्याति खाता नाम, A और B के पूँजी खातों से ₹50,000"], explanation: "A: 3/5 − 1/2 = 1/10 का त्याग; B को 1/10 का लाभ। B, A की क्षतिपूर्ति करता है: 50,000 × 1/10 = ₹5,000।" },
  "s12acc-p-037": { stem: "C के प्रवेश पर सभी समायोजनों के बाद A और B की पूँजी ₹90,000 और ₹60,000 है। C को 1/4 हिस्से के लिए प्रवेश दिया जाता है और उसे A तथा B की संयुक्त पूँजी के आधार पर अपने हिस्से के अनुपात में पूँजी लानी है। C की पूँजी है:", options: ["₹37,500","₹60,000","₹45,000","₹50,000"], explanation: "A और B मिलकर 3/4 रखते हैं, अतः कुल पूँजी = 1,50,000 × 4/3 = 2,00,000; C का 1/4 हिस्सा = ₹50,000। ₹37,500 में गलती से 1,50,000 का 1/4 लिया गया है।" },
  "s12acc-b-039": { stem: "कंपनी अधिनियम, 2013 की अनुसूची III के अनुसार तैयार कंपनी के तुलन पत्र में 'दीर्घकालिक प्रावधान' किस मुख्य शीर्षक के अंतर्गत आते हैं?", options: ["गैर-चालू देयताएँ","चालू देयताएँ","अंशधारकों की निधियाँ","गैर-चालू परिसंपत्तियाँ"], explanation: "गैर-चालू देयताओं में दीर्घकालिक ऋण, आस्थगित कर देयताएँ (शुद्ध), अन्य दीर्घकालिक देयताएँ और दीर्घकालिक प्रावधान शामिल हैं।" },
  "s12acc-b-040": { stem: "अनुसूची III के अनुसार 'बकाया याचना' दिखाई जाती है:", options: ["चालू परिसंपत्तियों के अंतर्गत व्यापारिक प्राप्य के रूप में","अंश पूँजी की टिप्पणियों में 'अभिदत्त परंतु पूर्णदत्त नहीं' पूँजी से घटाकर","अन्य चालू देयताओं के अंतर्गत","संचय एवं आधिक्य से घटाकर"], explanation: "अदत्त याचनाएँ अंश पूँजी संबंधी खातों की टिप्पणियों में अभिदत्त पूँजी की याचित राशि से घटाई जाती हैं; इन्हें परिसंपत्ति नहीं माना जाता।" },
  "s12acc-b-041": { stem: "अनुसूची III के अनुसार, जहाँ कंपनी का सामान्य प्रचालन चक्र पहचाना न जा सके, वहाँ इसे माना जाता है:", options: ["छह माह","चौबीस माह","बारह माह","सबसे पुराने बकाया देनदार की अवधि"], explanation: "चालू/गैर-चालू वर्गीकरण प्रचालन चक्र पर आधारित है; जब यह पहचाना न जा सके, तो इसकी अवधि बारह माह मानी जाती है।" },
  "s12acc-b-042": { stem: "एक कंपनी की चालू परिसंपत्तियाँ ₹3,00,000 और चालू देयताएँ ₹1,20,000 हैं। इसका चालू अनुपात है:", options: ["2 : 1","0.4 : 1","1.8 : 1","2.5 : 1"], explanation: "चालू अनुपात = चालू परिसंपत्तियाँ/चालू देयताएँ = 3,00,000/1,20,000 = 2.5 : 1।" },
  "s12acc-b-043": { stem: "चालू परिसंपत्तियाँ ₹2,40,000 हैं, जिनमें ₹60,000 का स्टॉक और ₹10,000 के पूर्वदत्त व्यय शामिल हैं। चालू देयताएँ ₹1,00,000 हैं। त्वरित (तरल) अनुपात है:", options: ["1.7 : 1","1.8 : 1","2.4 : 1","2.3 : 1"], explanation: "त्वरित परिसंपत्तियों में स्टॉक और पूर्वदत्त व्यय शामिल नहीं: 2,40,000 − 60,000 − 10,000 = 1,70,000; अनुपात = 1.7 : 1। केवल स्टॉक घटाने पर 1.8 आता।" },
  "s12acc-b-044": { stem: "एक कंपनी का दीर्घकालिक ऋण ₹4,00,000 और अंशधारकों की निधियाँ ₹5,00,000 हैं। इसका ऋण-समता अनुपात है:", options: ["1.25 : 1","0.8 : 1","0.44 : 1","0.2 : 1"], explanation: "ऋण-समता अनुपात = दीर्घकालिक ऋण/अंशधारकों की निधियाँ = 4,00,000/5,00,000 = 0.8 : 1।" },
  "s12acc-b-045": { stem: "समरूप (सामान्य आकार) लाभ-हानि विवरण में प्रत्येक मद को किसके प्रतिशत के रूप में व्यक्त किया जाता है?", options: ["कुल परिसंपत्तियाँ","शुद्ध लाभ","प्रचालन से आगम","कुल व्यय"], explanation: "समरूप आय विवरण में प्रचालन से आगम को 100 माना जाता है; समरूप तुलन पत्र में आधार कुल परिसंपत्तियाँ (या कुल समता एवं देयताएँ) होती हैं।" },
  "s12acc-b-046": { stem: "दो वर्षों का तुलनात्मक लाभ-हानि विवरण सामान्यतः दर्शाता है:", options: ["प्रत्येक मद केवल प्रचालन से आगम के प्रतिशत के रूप में","केवल दोनों वर्षों के अनुपात","केवल रोकड़ अंतर्वाह और बहिर्वाह","दोनों वर्षों की राशियाँ, निरपेक्ष परिवर्तन और प्रतिशत परिवर्तन"], explanation: "तुलनात्मक विवरण आँकड़ों को साथ-साथ रखकर निरपेक्ष और प्रतिशत परिवर्तन दिखाते हैं; मदों को आगम के प्रतिशत में दिखाना समरूप तकनीक है।" },
  "s12acc-b-047": { stem: "AS-3 के अनुसार तैयार रोकड़ प्रवाह विवरण में मशीनरी के क्रय पर चुकाया गया नकद किस रूप में वर्गीकृत होता है?", options: ["निवेश गतिविधि","प्रचालन गतिविधि","वित्तीय गतिविधि","गैर-नकद मद, दिखाई नहीं जाती"], explanation: "AS-3 के अनुसार दीर्घकालिक परिसंपत्तियों का अधिग्रहण और निपटान निवेश गतिविधियाँ हैं।" },
  "s12acc-b-048": { stem: "AS-3 के अनुसार कोई निवेश सामान्यतः रोकड़ तुल्य तभी माना जाता है जब वह:", options: ["किसी मान्यता प्राप्त स्टॉक एक्सचेंज पर सूचीबद्ध हो","अधिग्रहण की तिथि से लगभग तीन माह या उससे कम की अल्प परिपक्वता वाला हो","तुलन पत्र की तिथि से एक वर्ष तक की परिपक्वता वाला हो","किसी अन्य कंपनी के समता अंशों में हो"], explanation: "रोकड़ तुल्य अल्पकालिक, अत्यधिक तरल निवेश हैं जो ज्ञात राशि के नकद में सरलता से परिवर्तनीय हों और मूल्य परिवर्तन का जोखिम नगण्य हो, सामान्यतः अधिग्रहण से तीन माह या कम की परिपक्वता। समता अंश इसमें शामिल नहीं।" },
  "s12acc-b-049": { stem: "प्रचालन से आगम की लागत (बेचे गए माल की लागत) ₹4,80,000 है। प्रारंभिक स्टॉक ₹70,000 और अंतिम स्टॉक ₹90,000 है। स्टॉक (मालसूची) आवर्त अनुपात है:", options: ["5.33 गुना","6.86 गुना","6 गुना","8 गुना"], explanation: "औसत स्टॉक = (70,000 + 90,000)/2 = 80,000; अनुपात = 4,80,000/80,000 = 6 गुना।" },
  "s12acc-b-050": { stem: "प्रचालन से आगम ₹6,00,000 और प्रचालन से आगम की लागत ₹4,50,000 है। सकल लाभ अनुपात है:", options: ["75%","33.33%","20%","25%"], explanation: "सकल लाभ = 1,50,000; सकल लाभ अनुपात = 1,50,000/6,00,000 × 100 = 25%। 33.33% में गलती से लागत से भाग दिया गया है।" },
  "s12acc-p-038": { stem: "कर पूर्व शुद्ध लाभ ₹2,00,000; मूल्यह्रास ₹30,000; मशीनरी की बिक्री पर लाभ ₹10,000; व्यापारिक प्राप्य में वृद्धि ₹25,000; स्टॉक में कमी ₹15,000; व्यापारिक देय में वृद्धि ₹12,000। कर की उपेक्षा करते हुए, प्रचालन गतिविधियों से रोकड़ प्रवाह (अप्रत्यक्ष विधि) है:", options: ["₹2,22,000","₹2,42,000","₹2,18,000","₹1,70,000"], explanation: "2,00,000 + 30,000 − 10,000 − 25,000 + 15,000 + 12,000 = ₹2,22,000। बिक्री पर लाभ निवेश गतिविधि का है, अतः घटाया जाता है।" },
  "s12acc-p-039": { stem: "AS-3 के अनुसार, जो कंपनी वित्तीय उद्यम नहीं है, उसके लिए निम्नलिखित में से कौन-सा वर्गीकरण सही है?", options: ["चुकाया गया ब्याज: प्रचालन; प्राप्त लाभांश: प्रचालन","चुकाया गया ब्याज: वित्तीय; प्राप्त ब्याज और लाभांश: निवेश","चुकाया गया ब्याज: निवेश; चुकाया गया लाभांश: प्रचालन","प्राप्त ब्याज: वित्तीय; चुकाया गया लाभांश: निवेश"], explanation: "गैर-वित्तीय उद्यम के लिए चुकाया गया ब्याज और लाभांश वित्तीय गतिविधियाँ हैं, जबकि प्राप्त ब्याज और लाभांश निवेश गतिविधियाँ हैं। वित्तीय उद्यम के लिए चुकाया और प्राप्त ब्याज प्रचालन गतिविधि है।" },
  "s12acc-p-040": { stem: "मशीनरी (अपलिखित मूल्य पर): प्रारंभिक ₹5,00,000, अंतिम ₹5,80,000। वर्ष का मूल्यह्रास ₹60,000। ₹40,000 पुस्तक मूल्य की एक मशीन ₹8,000 लाभ पर बेची गई। केवल इन मदों को ध्यान में रखते हुए, निवेश गतिविधियों में प्रयुक्त शुद्ध रोकड़ है:", options: ["₹1,80,000","₹1,40,000","₹1,32,000","₹2,28,000"], explanation: "क्रय = 5,80,000 − 5,00,000 + 60,000 + 40,000 = 1,80,000 (बहिर्वाह)। बिक्री से प्राप्ति = 40,000 + 8,000 = 48,000 (अंतर्वाह)। शुद्ध प्रयुक्त = ₹1,32,000।" },
  "s12acc-p-041": { stem: "अभिकथन (A): अनुसूची III के अनुसार लाभ-हानि विवरण में 'प्रचालन से आगम' और 'अन्य आय' अलग-अलग दिखाए जाते हैं।\nकारण (R): एक विनिर्माण कंपनी द्वारा सावधि जमा पर अर्जित ब्याज उसके प्रचालन से आगम का भाग है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"], explanation: "A सत्य है। R असत्य है: गैर-वित्तीय कंपनी के लिए सावधि जमा पर ब्याज उसके मुख्य प्रचालन से नहीं है और अन्य आय के रूप में दिखाया जाता है।" },
  "s12acc-p-042": { stem: "कर पश्चात शुद्ध लाभ ₹3,00,000 और कर दर 25% है। कंपनी के ₹10,00,000 के 10% ऋणपत्र हैं। ब्याज आवरण अनुपात है:", options: ["4 गुना","3 गुना","6 गुना","5 गुना"], explanation: "कर पूर्व लाभ = 3,00,000/0.75 = 4,00,000; ब्याज = 1,00,000; ब्याज एवं कर पूर्व लाभ = 5,00,000; अनुपात = 5,00,000/1,00,000 = 5 गुना। 4 गुना में गलती से कर पूर्व लाभ लिया गया है।" },
  "s12acc-p-043": { stem: "एक कंपनी का चालू अनुपात 2 : 1 है। निम्नलिखित में से कौन-सा लेन-देन इसे बढ़ाएगा?", options: ["व्यापारिक देय का नकद भुगतान","उधार स्टॉक का क्रय","व्यापारिक प्राप्य से नकद वसूली","तीन माह के उधार पर मशीनरी का क्रय"], explanation: "अनुपात 1 से अधिक हो तो चालू परिसंपत्तियों और चालू देयताओं दोनों में बराबर कमी उसे बढ़ाती है (जैसे 200/100 से 180/80 = 2.25)। उधार स्टॉक क्रय उसे घटाता है; देनदारों से वसूली अपरिवर्तित रखती है; मशीनरी हेतु उधार केवल देयताएँ बढ़ाता है।" },
  "s12acc-p-044": { stem: "उधार प्रचालन आगम ₹6,00,000 है। व्यापारिक प्राप्य वर्ष के आरंभ में ₹1,10,000 और अंत में ₹90,000 हैं। व्यापारिक प्राप्य आवर्त अनुपात और औसत संग्रह अवधि (वर्ष में 12 माह मानकर) हैं:", options: ["5.45 गुना और 2.2 माह","6 गुना और 2 माह","6.67 गुना और 1.8 माह","5 गुना और 2.4 माह"], explanation: "औसत प्राप्य = (1,10,000 + 90,000)/2 = 1,00,000; आवर्त = 6,00,000/1,00,000 = 6 गुना; संग्रह अवधि = 12/6 = 2 माह।" },
  "s12acc-p-045": { stem: "प्रचालन से आगम ₹6,00,000; प्रचालन से आगम की लागत ₹3,60,000; प्रचालन व्यय ₹60,000। प्रचालन अनुपात है:", options: ["60%","10%","70%","30%"], explanation: "प्रचालन अनुपात = (3,60,000 + 60,000)/6,00,000 × 100 = 70%; अतः प्रचालन लाभ अनुपात 30% है।" },
  "s12acc-p-046": { stem: "ब्याज एवं कर पूर्व लाभ ₹2,40,000 है। अंशधारकों की निधियाँ ₹12,00,000 और गैर-चालू देयताएँ (दीर्घकालिक ऋण) ₹4,00,000 हैं। निवेश पर प्रत्याय (नियोजित पूँजी पर) है:", options: ["20%","12%","60%","15%"], explanation: "नियोजित पूँजी = 12,00,000 + 4,00,000 = 16,00,000; निवेश पर प्रत्याय = 2,40,000/16,00,000 × 100 = 15%। केवल अंशधारकों की निधियाँ लेने पर 20% आता।" },
  "s12acc-p-047": { stem: "तुलनात्मक लाभ-हानि विवरण से: प्रचालन से आगम ₹10,00,000 से बढ़कर ₹12,50,000 हो गया, और कुल व्यय ₹7,00,000 से बढ़कर ₹9,10,000 हो गए। कर पूर्व लाभ में प्रतिशत परिवर्तन है:", options: ["13.33% वृद्धि","25% वृद्धि","30% वृद्धि","40% वृद्धि"], explanation: "कर पूर्व लाभ 3,00,000 से बढ़कर 3,40,000; परिवर्तन = 40,000/3,00,000 × 100 = 13.33%। 25% आगम की वृद्धि और 30% व्यय की वृद्धि है।" },
  "s12acc-p-048": { stem: "सूची I (मद) को सूची II (अनुसूची III तुलन पत्र का मुख्य शीर्षक) से सुमेलित कीजिए।\nसूची I: A. अदत्त लाभांश  B. ख्याति  C. खुले औज़ार  D. पाँच वर्ष बाद शोधनीय ऋणपत्र\nसूची II: 1. गैर-चालू देयताएँ  2. चालू देयताएँ  3. गैर-चालू परिसंपत्तियाँ  4. चालू परिसंपत्तियाँ", options: ["A-1, B-3, C-4, D-2","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-1, D-4"], explanation: "अदत्त लाभांश अन्य चालू देयता है; ख्याति अमूर्त (गैर-चालू) परिसंपत्ति है; खुले औज़ार स्टॉक (चालू परिसंपत्तियों) में शामिल हैं; दीर्घावधि ऋणपत्र दीर्घकालिक ऋण हैं।" },
  "s12acc-p-049": { stem: "निम्नलिखित में से कौन-सा गैर-नकद लेन-देन है जिसे AS-3 के अनुसार रोकड़ प्रवाह विवरण से बाहर रखा जाता है?", options: ["ऋणपत्रों का नकद शोधन","अंतरिम लाभांश का भुगतान","ऋणपत्रों का समता अंशों में परिवर्तन","निवेशों की नकद बिक्री"], explanation: "नकद से रहित निवेश और वित्तीय लेन-देन, जैसे ऋण का समता में परिवर्तन या अंश जारी करके परिसंपत्तियाँ खरीदना, बाहर रखे जाते हैं और अन्यत्र प्रकट किए जाते हैं।" },
  "s12acc-p-050": { stem: "एक कंपनी की कुल परिसंपत्तियाँ ₹15,00,000, चालू देयताएँ ₹3,00,000 और दीर्घकालिक ऋण ₹4,00,000 हैं; कोई अन्य देयता नहीं है। इसका ऋण-समता अनुपात है:", options: ["0.875 : 1","0.33 : 1","0.27 : 1","0.5 : 1"], explanation: "अंशधारकों की निधियाँ = 15,00,000 − 3,00,000 − 4,00,000 = 8,00,000; ऋण-समता = 4,00,000/8,00,000 = 0.5 : 1। इस अनुपात में चालू देयताएँ ऋण नहीं मानी जातीं।" },
};
